			function sggSelect(cptvSeCd){
			    
			    // 2022-09-22 YOO.CHI.HOON
			    if (ValueUtil.isNull(cptvSeCd)) return false;     // 시도구분코드
			    
			    var vcLv1Cmb = app.lookup("cmb_CTPV_NM");        // 시도콤보박스
			    var vcLv2Cmb = app.lookup("cmb_SGG_NM");         // 시군구콤보박스
			    
			    vcLv2Cmb.setFilter("value == '' || getValue('CTPV_SE_CD') =='" + cptvSeCd + "'");
			    
			    if (vcLv1Cmb.value == "36"){            //시종특별자치시
			        util.Control.setEnable(app, false, "cmb_SGG_NM");
			    }else{
			        util.Control.setEnable(app, true , "cmb_SGG_NM");
			    }
			    // 시도구분코드 변경시 시군구 콤보 초기화
			    vcLv2Cmb.putValue("");    
			}

